<template>
  <div class="page-wrap">
    <div class="page-head"><div><h3>Laporan Lembur</h3><p>Jam lembur per tanggal berdasarkan kalender aktif dan lembur yang sudah disetujui.</p></div><button class="btn btn-sm btn-outline-primary" :disabled="loading" @click="load">Refresh</button></div>
    <div class="summary-grid"><div class="summary"><span>Total Jam</span><b>{{data.grand_total||0}}</b></div><div class="summary"><span>Jam Hari Normal</span><b>{{data.grand_normal||0}}</b></div><div class="summary"><span>Jam Hari Libur</span><b>{{data.grand_libur||0}}</b></div><div class="summary"><span>Upah + Transport</span><b>{{money(data.grand_bayar)}}</b></div></div>
    <div class="card"><div class="toolbar"><input v-model="bulan" type="month" class="form-control form-control-sm" @change="load"><button class="btn btn-sm btn-outline-success" :disabled="loading" @click="exportFile('excel')">Excel</button><button class="btn btn-sm btn-outline-danger" :disabled="loading" @click="exportFile('pdf')">PDF</button></div>
      <div v-if="loading" class="state">Memuat laporan...</div>
      <div v-else class="table-responsive"><table class="table table-sm table-bordered align-middle overtime-table"><thead><tr><th class="sticky">No</th><th class="sticky">NIP</th><th class="sticky name">Nama</th><th>Unit</th><th v-for="day in data.days||[]" :key="day" :class="dayClass(day)"><span>{{day}}</span><small>{{dayType(day)}}</small></th><th>Total Jam</th><th>Jam Normal</th><th>Jam Libur</th><th>Upah Lembur</th><th>Transport</th><th>Total Bayar</th></tr></thead>
      <tbody><tr v-for="(r,i) in data.rows||[]" :key="r.pegawai_id"><td>{{i+1}}</td><td>{{r.nip}}</td><td class="name">{{r.nama}}</td><td>{{r.unit_kerja||r.divisi||'-'}}</td><td v-for="day in data.days||[]" :key="`${r.pegawai_id}-${day}`" :class="dayClass(day)" :title="dayTitle(day)">{{Number(r.harian?.[day]||0)>0?Number(r.harian[day]).toFixed(2):'–'}}</td><td>{{r.total_jam}}</td><td>{{r.total_jam_normal}}</td><td>{{r.total_jam_libur}}</td><td>{{money(r.total_upah_lembur)}}</td><td>{{money(r.total_transport)}}</td><td><strong>{{money(r.total_bayar)}}</strong></td></tr><tr v-if="!(data.rows||[]).length"><td :colspan="(data.days||[]).length+10" class="text-center text-muted">Tidak ada data lembur disetujui.</td></tr></tbody>
      <tfoot><tr><th colspan="4" class="text-end">TOTAL</th><th v-for="day in data.days||[]" :key="`total-${day}`" :class="dayClass(day)">{{Number(data.daily_totals?.[day]||0).toFixed(2)}}</th><th>{{data.grand_total||0}}</th><th>{{data.grand_normal||0}}</th><th>{{data.grand_libur||0}}</th><th>{{money(data.grand_upah)}}</th><th>{{money(data.grand_transport)}}</th><th>{{money(data.grand_bayar)}}</th></tr></tfoot></table></div>
      <p class="legend"><span class="normal-key">Hari Normal</span><span class="holiday-key">Hari Libur / Cuti Bersama / akhir pekan</span> · nilai harian menunjukkan total jam lembur disetujui.</p>
    </div>
  </div>
</template>
<script setup>
import {onMounted,ref} from 'vue';import Swal from 'sweetalert2';import api from '../../services/api'
const loading=ref(false);const now=new Date();const bulan=ref(`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`);const data=ref({rows:[],days:[]})
const money=v=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(v||0))
function dayType(day){const x=data.value.daily_types?.[day];return x?.is_hari_libur?'LIBUR':'NORMAL'}
function dayClass(day){return data.value.daily_types?.[day]?.is_hari_libur?'holiday':'normal'}
function dayTitle(day){const x=data.value.daily_types?.[day];return x?.nama_kalender||x?.jenis_hari||'Hari Normal'}
async function load(){loading.value=true;try{const r=await api.get('/kehadiran/laporan-lembur',{params:{bulan:bulan.value}});data.value=r.data?.data||{rows:[],days:[]}}catch(e){Swal.fire('Gagal','Gagal memuat laporan lembur.','error')}finally{loading.value=false}}
async function exportFile(type){try{const r=await api.get(`/kehadiran/laporan-lembur/export-${type}`,{params:{bulan:bulan.value},responseType:'blob'});const url=URL.createObjectURL(new Blob([r.data],{type:r.headers['content-type']}));const a=document.createElement('a');a.href=url;a.download=`laporan-lembur-${bulan.value}.${type==='excel'?'xls':'pdf'}`;a.click();URL.revokeObjectURL(url)}catch(e){Swal.fire('Gagal','Gagal mengekspor laporan.','error')}}
onMounted(load)
</script>
<style scoped>.page-head{display:flex;justify-content:space-between;margin-bottom:12px}.page-head h3{margin:0;font-weight:800}.page-head p{margin:2px 0;color:#64748b;font-size:12px}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}.summary{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:12px}.summary span{display:block;color:#64748b;font-size:11px}.summary b{font-size:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:12px}.toolbar{display:flex;gap:8px;margin-bottom:10px}.toolbar input{max-width:160px}.overtime-table{font-size:11px;white-space:nowrap}.overtime-table th,.overtime-table td{text-align:center;vertical-align:middle}.overtime-table th small{display:block;font-size:8px}.overtime-table .name{text-align:left;min-width:160px}.overtime-table .sticky{background:#f8fafc}.overtime-table .normal{background:#f0fdf4}.overtime-table .holiday{background:#fff1f2}.overtime-table thead th{position:sticky;top:0;z-index:2}.legend{font-size:11px;color:#64748b;margin:10px 0 0}.normal-key,.holiday-key{display:inline-block;padding:3px 7px;border-radius:5px;margin-right:5px}.normal-key{background:#f0fdf4}.holiday-key{background:#fff1f2}@media(max-width:900px){.summary-grid{grid-template-columns:repeat(2,1fr)}}</style>
